import React from 'react';

function RulesModal({ onAccept, onLater }) {
  return (
    <div className="min-h-screen bg-gradient-to-br from-[#FF6B35]/10 to-[#1A1A2E] flex items-center justify-center p-4">
      <div className="bg-white/10 backdrop-blur-lg rounded-3xl p-8 max-w-md w-full border border-white/20">
        <div className="text-center mb-6">
          <span className="text-6xl block mb-3">📋</span>
          <h2 className="text-2xl font-bold text-white">قوانین و راهنمایی</h2>
          <p className="text-sm text-gray-400 mt-1">لطفاً قبل از شروع مطالعه کنید</p>
        </div>
        <div className="max-h-60 overflow-y-auto text-sm space-y-2 text-gray-300 p-3 bg-black/30 rounded-2xl">
          <div className="flex gap-2"><span className="text-[#FF6B35] font-bold">۱.</span><span>تمرکز روی فعال‌سازی سطح باشگاه VIP</span></div>
          <div className="flex gap-2"><span className="text-[#FF6B35] font-bold">۲.</span><span>معرفی دوستان و دریافت ۱۰٪ از واریز آن‌ها</span></div>
          <div className="flex gap-2"><span className="text-[#FF6B35] font-bold">۳.</span><span>انجام ماموریت‌های روزانه برای افزایش موجودی</span></div>
          <div className="flex gap-2"><span className="text-[#FF6B35] font-bold">۴.</span><span>حداقل برداشت: ۵۰۰ TON</span></div>
          <div className="flex gap-2"><span className="text-[#FF6B35] font-bold">۵.</span><span>ماینرها ۳۰ روز فعالیت دارند</span></div>
          <div className="flex gap-2"><span className="text-[#FF6B35] font-bold">۶.</span><span>تمام موجودی‌ها باید به TON تبدیل شوند</span></div>
          <div className="flex gap-2"><span className="text-[#FF6B35] font-bold">۷.</span><span>ورود روزانه برای دریافت پاداش زنجیره‌ای</span></div>
          <div className="flex gap-2"><span className="text-[#FF6B35] font-bold">۸.</span><span>تقویت ماینرها: ۳۰ دقیقه سرعت دو برابر</span></div>
          <div className="flex gap-2"><span className="text-[#FF6B35] font-bold">۹.</span><span>تقلب = بستن یک‌طرفه حساب</span></div>
          <div className="flex gap-2"><span className="text-[#FF6B35] font-bold">۱۰.</span><span>بازخورد = دریافت پاداش</span></div>
        </div>
        <div className="flex gap-3 mt-6">
          <button onClick={onAccept} className="flex-1 py-3 bg-gradient-to-r from-[#FF6B35] to-orange-500 text-white rounded-2xl font-bold hover:scale-105 transition-all shadow-lg">
            📖 رفتن به قوانین
          </button>
          <button onClick={onLater} className="flex-1 py-3 bg-white/10 text-white rounded-2xl font-bold hover:bg-white/20 transition-all border border-white/20">
            باشه بعداً
          </button>
        </div>
      </div>
    </div>
  );
}

export default RulesModal;